<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { listCases,reviewCase } from '../../api/case';import { text,tagType,formatDate } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,loading:false});const open=ref(false);const current=ref({});const form=reactive({reviewResult:'APPROVED',reviewComment:''});const load=async()=>{state.loading=true;try{const r=await listCases('/admin/case-reviews',state);state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const show=(row)=>{current.value=row;Object.assign(form,{reviewResult:'APPROVED',reviewComment:''});open.value=true};const save=async()=>{try{await reviewCase(current.value.id,form);ElMessage.success('审核结果已保存');open.value=false;load()}catch(e){ElMessage.error(messageOf(e))}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="案件审核" description="审核客户提交的案件委托，结果将写入审核历史"/><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="caseName" label="案件名称" min-width="230"/><el-table-column label="案件类型" width="120"><template #default="{row}">{{text('caseType',row.caseType)}}</template></el-table-column><el-table-column label="优先级" width="90"><template #default="{row}"><el-tag :type="tagType(row.priorityLevel)">{{text('priority',row.priorityLevel)}}</el-tag></template></el-table-column><el-table-column label="提交时间" width="160"><template #default="{row}">{{formatDate(row.submitTime)}}</template></el-table-column><el-table-column width="90"><template #default="{row}"><el-button type="primary" link @click="show(row)">审核</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" title="案件委托审核" width="min(560px,94vw)"><p class="dialog-lead">{{current.caseName}}</p><el-form label-position="top"><el-form-item label="审核结果"><el-radio-group v-model="form.reviewResult"><el-radio-button value="APPROVED">通过</el-radio-button><el-radio-button value="RETURNED">退回修改</el-radio-button><el-radio-button value="REJECTED">拒绝</el-radio-button></el-radio-group></el-form-item><el-form-item label="审核意见"><el-input v-model="form.reviewComment" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">提交审核</el-button></template></el-dialog></div></template>
